package com.example.starter.evidence.domain;

/**
 * 证据生命周期状态。
 */
public enum EvidenceStatus {
    /** 可保留：未处于任何未确认清除批次。 */
    ACTIVE,
    /** 已标记：进入未确认的清除批次，仍可被新保全救回。 */
    MARKED,
    /** 已清除：最终确认完成，不可再被保全。 */
    PURGED
}

package com.example.starter.evidence.domain;

/**
 * 法律保全单状态。
 */
public enum HoldStatus {
    /** 生效中：覆盖的证据不可被清除标记。 */
    ACTIVE,
    /** 已解除：不再阻止清除。 */
    RELEASED
}

package com.example.starter.evidence.domain;

/**
 * 清除批次状态。
 */
public enum PurgeBatchStatus {
    /** 已标记：候选清单已原子写入，等待最终确认。 */
    MARKED,
    /** 已确认：清除清单已冻结，不可变。 */
    CONFIRMED
}

package com.example.starter.evidence.domain;

/**
 * 清除批次候选项的最终结果。
 */
public enum PurgeItemStatus {
    /** 已清除：最终确认时仍满足清除条件。 */
    PURGED,
    /** 已救回：确认前出现生效保全，恢复为可保留状态。 */
    RESCUED
}

package com.example.starter.evidence.domain;

/**
 * 证据保管事件类型，事件仅追加不可变。
 */
public enum CustodyEventType {
    /** 证据登记。 */
    REGISTERED,
    /** 证据被保全单覆盖。 */
    HOLD_CREATED,
    /** 证据所属保全单解除。 */
    HOLD_RELEASED,
    /** 证据被清除批次标记。 */
    MARKED,
    /** 证据在确认前被新保全救回。 */
    RESCUED,
    /** 证据被最终确认清除。 */
    PURGED
}

